-- Second Italian article translations batch (deepening phase). Same 3
-- additional articles as the German/Spanish batch 2: Things to do in
-- Maldives, Most Famous Places In The World, and the Maldives Honeymoon
-- guide. entity_id resolved via scalar subquery on the canonical English
-- slug (see the entity_id fix commit for why this matters).
insert into translations (entity_id, entity_type, locale, slug, title, short_description, description, body_html, meta_title, meta_description, translation_status, translated_by) values
  ((select id from nodes where node_type = 'article' and slug = 'things-to-do-in-maldives'), 'article', 'it', 'cose-da-fare-alle-maldive', 'Cose da fare alle Maldive', 'Le 12 migliori attività da fare alle Maldive durante la vostra vacanza. La maggior parte di queste attività è disponibile in tutti i resort.', null, '<h3>Snorkeling</h3><p>Le Maldive offrono alcune delle esperienze di snorkeling più spettacolari al mondo. Questo è dovuto all''abbondanza di barriere coralline nella regione, così come alle acque estremamente limpide. Esistono infatti quasi 70 specie distinte di barriere coralline e più di 700 specie di vita marina. Ciò significa che, facendo snorkeling qui, vedrete sicuramente una straordinaria varietà di flora e fauna. Tra le specie che è probabile avvistare ci sono squali di barriera, varie specie di tartarughe, razze, pesci Napoleone e murene. Che siate esperti di vita marina o no, potrete comunque apprezzare la colorata varietà di creature che riuscirete a osservare. Lo snorkeling è un''attività altamente raccomandata alle Maldive.</p><figure><img src="legacy/images/articles/snorkeling.webp" alt="maldives" loading="lazy" /></figure><h3>Immersioni</h3><p>Le Maldive sono diventate una delle migliori destinazioni di immersione al mondo grazie alle spiagge di sabbia bianca, alle barriere coralline, alle acque calde e limpide, ai numerosi siti di immersione e alla ricca vita marina.</p><p>La maggior parte dei resort alle Maldive dispone di una struttura per le immersioni, ed esistono numerosi operatori di crociere liveaboard che offrono vacanze di immersione portando gli ospiti in molti siti di immersione in tutte le Maldive. Molti sub desiderano immergersi alle Maldive per la presenza di squali balena, mante, razze aquila, squali di barriera, squali martello e murene, oltre a numerose specie più piccole di pesci e corallo. Le immersioni sono una delle migliori attività da fare alle Maldive.</p><figure><img src="legacy/images/articles/maldives-diving.webp" alt="maldives" loading="lazy" /></figure><h3>Pesca</h3><p>Rinomate come una delle migliori destinazioni al mondo per la pesca d''altura, le Maldive ospitano un''abbondanza di pesci pelagici come tonno, lampuga, pesce serra, barracuda e pesce spada. Le Maldive hanno regolamenti di pesca rigorosi che vengono ampiamente applicati per mantenere gli stock di pesce a sostegno del sostentamento della popolazione locale.</p><figure><img src="legacy/images/articles/fishing.webp" alt="maldives" loading="lazy" /></figure><h3>Spiagge</h3><p>Le spiagge delle Maldive sono famose per il loro candore e per le acque cristalline. In alcune zone delle Maldive, le spiagge possono brillare durante la notte, fenomeno causato dal plancton marino. La spiaggia di <a href="/maldives/islands/fuvahmulah/">Fuvahmulah</a> è famosa per le sue pietre luminose.</p><figure><img src="legacy/images/articles/maldives-sand-bank.webp" alt="maldives" loading="lazy" /></figure><h3>Yoga</h3><p>Lo yoga è un insieme di pratiche fisiche, mentali e spirituali originatesi nell''antica India. Lo yoga è una delle sei scuole ortodosse delle tradizioni filosofiche hindu. Nei resort delle Maldive viene offerta un''ampia varietà di sessioni di yoga; il momento migliore per praticarlo è all''alba e al tramonto.</p><h3>Spa</h3><p>Quasi tutti i resort delle Maldive offrono molti tipi di massaggi corporei. Sono presenti anche numerosi marchi spa internazionalmente famosi.</p><h3>Cene sott''acqua</h3><p>Le Maldive ospitano il primo ristorante sottomarino al mondo. In totale sono disponibili 6 ristoranti sottomarini in diverse zone. Costruiti diversi metri sotto il livello del mare, questi ristoranti offrono vedute spettacolari della vita marina attraverso soffitti di vetro, ridefinendo completamente l''esperienza della cena sott''acqua alle Maldive.</p><h3>Island hopping</h3><p>L''island hopping è il modo migliore per scoprire la cultura e la storia locale delle Maldive. Ci sono 200 isole locali in tutte le Maldive, e quasi tutti i resort e gli hotel offrono escursioni ai turisti per visitare queste isole locali.</p><p>La città di Malé è la capitale delle Maldive ed è un luogo straordinario con numerosi siti importanti e interessanti. Se si soggiorna in un resort, il modo migliore per visitare la capitale è il giorno della partenza: arrivate in anticipo all''aeroporto internazionale di Malé e fate il tragitto di 10 minuti dall''aeroporto. Questa è una delle migliori cose da fare se avete tempo di attesa all''aeroporto di Malé.</p><figure><img src="legacy/images/articles/day-tours-to-villages.webp" alt="maldives" loading="lazy" /></figure><h3>Sommergibile per l''osservazione delle balene</h3><p>Il sommergibile per l''osservazione delle balene è l''opzione migliore per chi non sa nuotare o non può immergersi. La vita marina delle Maldive è il patrimonio più ricco del paese. Se per qualsiasi motivo non riuscite a immergervi o andare sott''acqua, non preoccupatevi: le Maldive offrono escursioni in sommergibile per l''osservazione delle balene.</p><h3>Surf</h3><p>Il surf alle Maldive è influenzato dai monsoni di nord-est e di sud-ovest. Durante il monsone di nord-est (da marzo ad aprile), le condizioni sono ottimali negli atolli meridionali. Da maggio a ottobre, durante il monsone di sud-ovest, la zona migliore per il surf si trova negli atolli settentrionali o centrali.</p><h3>Shopping alle Maldive</h3><p>Lo shopping di souvenir è molto apprezzato dai visitatori alle Maldive. I negozi di souvenir offrono articoli di produzione locale, corallo, conchiglie e numerosi oggetti artigianali. La città di Malé è il luogo più indicato per lo shopping di souvenir; sono disponibili anche acquisti online e consegna a domicilio.</p><figure><img src="legacy/images/articles/maldives-shopping.webp" alt="maldives" loading="lazy" /></figure><h3>Escursioni e sport acquatici</h3><p>Esistono molti altri tipi di escursioni e sport acquatici offerti alle Maldive. Di seguito alcune delle escursioni più comuni.</p><p>Osservazione delle mante Avvistamento delle balene Osservazione dei delfini Pasto per gli squali Pasto per le razze Crociera al tramonto Crociera all''alba Escursione all''equatore</p><p>Moto d''acqua Banana boat Kayak Windsurf Parasailing Sci d''acqua Giro in catamarano</p><figure><img src="legacy/images/articles/dolphin-cruise.webp" alt="maldives" loading="lazy" /></figure>', 'Cose da fare alle Maldive | Guida di Viaggio alle Maldive | MTG', 'Le 12 migliori attività da fare alle Maldive durante la vostra vacanza. La maggior parte di queste attività è disponibile in tutti i resort.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'most-famous-places-in-the-world'), 'article', 'it', 'i-luoghi-piu-famosi-del-mondo', 'I luoghi più famosi del mondo', 'Elenco dei luoghi e delle destinazioni più famose del mondo con curiosità per i turisti.', null, '<p>Autore: Shayad Saeed</p><p>Data: 02/02/2021</p><p>Esistono centinaia di luoghi famosi nel mondo, e tra questi ne metterò in evidenza i 10 più conosciuti secondo le mie ricerche. I monumenti ci danno un senso di luogo. Questi siti storici e meraviglie naturali ci legano a un luogo e ci invitano a visitarlo. La Torre Eiffel si trova a Parigi, e la Statua della Libertà si trova a New York City. Queste 10 attrazioni, tutte significative per le rispettive località e storie, dovrebbero essere nella vostra lista dei desideri di viaggio.</p><figure><img src="legacy/images/articles/ar/famous-places-in-the-world.webp" alt="famous places in the world" loading="lazy" /></figure><h4>Burj Khalifa, Dubai</h4><p>A Dubai, negli Emirati Arabi Uniti, il Burj Khalifa è un grattacielo. È la struttura e l''edificio più alto del mondo dal 2009, con un''altezza totale di 829,8 m (poco più di mezzo miglio), superando il precedente record, il Taipei 101. I seguenti primati sono associati al Burj Khalifa:</p><p>Questi primati lo rendono uno dei migliori luoghi al mondo.</p><figure><img src="legacy/images/articles/ar/famous-places-on-the-world.webp" alt="famous places on the world" loading="lazy" /></figure><h4>La Torre Eiffel, Francia</h4><p>La Torre Eiffel, conosciuta anche come La Tour Eiffel in francese, fu il punto centrale dell''Esposizione di Parigi del 1889. Fu costruita per celebrare il centenario della Rivoluzione Francese e per mostrare al resto del mondo la potenza industriale della Francia. In seguito divenne il simbolo della città per i seguenti motivi:</p><figure><img src="legacy/images/articles/ar/most-famous-places-in-the-world.webp" alt="most famous places in the world" loading="lazy" /></figure><h4>La Sydney Opera House</h4><p>La Sydney Opera House è un centro di arti performative con diverse sale a Sydney, nel Nuovo Galles del Sud, in Australia, situato sul porto di Sydney. È una delle strutture più conosciute e distintive del ventesimo secolo.</p><figure><img src="legacy/images/articles/ar/famous-destinations-in-the-world.webp" alt="famous destinations in the world" loading="lazy" /></figure><h4>Statua della Libertà: New York</h4><p>La Statua della Libertà è uno dei monumenti più conosciuti degli Stati Uniti, situata nel porto di New York. Il monumento fu costruito nel 1886 dal popolo francese per simboleggiare l''amicizia tra i due paesi, e fu designato Monumento Nazionale nel 1924. La statua è accessibile tramite traghetto da Battery Park, nella Lower Manhattan, che si ferma sia a Ellis Island che a Liberty Island.</p><figure><img src="legacy/images/articles/ar/best-places-in-the-world.webp" alt="best places in the world" loading="lazy" /></figure><h4>La Grande Piramide di Giza: Il Cairo, Egitto</h4><p>La Grande Piramide di Giza e le piramidi circostanti risalgono a oltre 4.000 anni fa. Si trovano appena fuori dal Cairo, lungo il fiume Nilo. Costruite intorno al 2500 a.C. dal re Cheope, queste antiche rovine sono anche una delle Sette Meraviglie del Mondo Antico, l''unica ancora in piedi oggi.</p><figure><img src="legacy/images/articles/ar/famous-destinations.webp" alt="famous destinations" loading="lazy" /></figure><h4>Marina Bay Sands, Singapore</h4><p>Il Marina Bay Sands è un hotel e centro commerciale nel distretto Downtown Core di Singapore. Al momento della sua apertura nel 2010, fu annunciato come la proprietà di casinò indipendente più costosa al mondo, con un costo di 8 miliardi di dollari di Singapore (6,88 miliardi di dollari USA), terreno incluso.</p><figure><img src="legacy/images/articles/ar/famous-places.webp" alt="famous places" loading="lazy" /></figure><h4>Taj Mahal: Agra, India</h4><p>Il Taj Mahal fu costruito per la moglie dell''imperatore Shah Jahan. L''UNESCO ha designato questo edificio, completato nel 1648, come il miglior esempio di architettura indo-islamica. Il Taj Mahal si trova nella città di Agra ed è accessibile dalla capitale New Delhi con un volo di un''ora o un viaggio in treno di tre ore. Vista la grande affluenza a questa attrazione, è meglio visitarla durante la settimana. L''alba getta un bagliore incantevole sulla struttura in marmo bianco.</p><figure><img src="legacy/images/articles/ar/famous-places-to-visit-in-the-world.webp" alt="famous places to visit in the world" loading="lazy" /></figure><h4>Isole Maldive</h4><p>Le Maldive sono una catena di 1.200 isole situate nell''Oceano Indiano. Le Maldive sono conosciute per la loro unicità e bellezza naturale. Per la loro posizione geografica, è consigliabile visitarle tra ottobre e maggio. Per i seguenti motivi, sono considerate uno dei migliori luoghi da visitare:</p><figure><img src="legacy/images/articles/ar/best-places-to-tavel-in-the-world.webp" alt="best places to tavel in the world" loading="lazy" /></figure><h4>Isola di Bora Bora</h4><p>Bora Bora è una piccola isola al largo della Polinesia (lunga solo circa 10 km e larga poco più di 3 km). Al suo centro si trova un vulcano inattivo che si apre in una rigogliosa giungla prima di confluire in una laguna color turchese. Questi dettagli la rendono una delle migliori destinazioni di viaggio:</p><figure><img src="legacy/images/articles/ar/famous-places-to-travel-in-the-world.webp" alt="famous places to-travel in the world" loading="lazy" /></figure><h4>Isola del Sud, Nuova Zelanda</h4><p>L''Isola del Sud della Nuova Zelanda è ricca di paesaggi maestosi a ogni angolo, ed è un''Area Patrimonio dell''Umanità UNESCO. I seguenti fatti la rendono uno dei luoghi più famosi da visitare.</p>', 'I luoghi più famosi del mondo | Guida di Viaggio alle Maldive | MTG', 'Elenco dei luoghi e delle destinazioni più famose del mondo con curiosità per i turisti.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-honeymoon-ultimate-romantic-getaway-guide'), 'article', 'it', 'luna-di-miele-alle-maldive-guida-romantica-definitiva', 'Luna di miele alle Maldive: la guida definitiva alla fuga romantica', 'Guida completa alla luna di miele alle Maldive: scoprite i migliori resort romantici, bungalow sull''acqua, pacchetti ed esperienze unica per la vostra vacanza di coppia perfetta nel paradiso.', null, '<figure><img src="legacy/images/maldives-honeymoons.webp" alt="Romantic Maldives honeymoon couple on beach" loading="lazy" /></figure><p>Le Maldive si confermano il paradiso indiscusso per le lune di miele, offrendo agli sposi novelli un''esquisita combinazione di bellezza naturale, privacy e romanticismo. Questo arcipelago di 1.192 isole coralline sparse nell''Oceano Indiano ha perfezionato l''arte delle vacanze di coppia, con resort progettati appositamente per creare esperienze romantiche indimenticabili.</p><p>Ciò che distingue le Maldive dalle altre destinazioni tropicali è la sua geografia unica: ogni resort occupa tipicamente la propria isola privata, garantendo un completo isolamento. I celebri bungalow sull''acqua, di cui le Maldive sono state pioniere, permettono alle coppie di svegliarsi al dolce lambire delle onde sotto la loro villa e immergersi direttamente in lagune cristalline.</p><p>Oltre alla bellezza fisica, i resort maldiviani si specializzano nel creare esperienze romantiche personalizzate. Dai picnic privati sui banchi di sabbia ai ristoranti sottomarini circondati da vita marina, le opportunità per creare momenti speciali sono infinite. La cultura musulmana del paese comporta che le manifestazioni pubbliche di affetto siano riservate alle isole resort, creando un''atmosfera discreta e intima, perfetta per le lune di miele.</p><h2>Perché le Maldive sono la destinazione definitiva per la luna di miele</h2><figure><img src="legacy/images/activities/virgin-islands-excursion.webp" alt="Private island in Maldives" loading="lazy" /></figure><p>Diversi fattori chiave rendono le Maldive la destinazione per luna di miele più importante al mondo:</p><h4>1. Privacy senza pari</h4><p>A differenza delle destinazioni balneari affollate, i resort maldiviani offrono un vero isolamento. La maggior parte occupa isole private con solo 50-150 ville, il che significa che spesso avrete intere distese di spiaggia tutte per voi. Le isole resort sono progettate con cura per massimizzare la privacy, con barriere vegetali tra gli alloggi.</p><h4>2. L''esperienza del bungalow sull''acqua</h4><p>Le Maldive hanno inventato il concetto della villa di lusso sull''acqua. Le versioni moderne presentano pannelli con pavimento in vetro, piscine a sfioro private e accesso diretto alla laguna. Leggete la nostra guida completa ai bungalow sull''acqua delle Maldive per scegliere quello perfetto.</p><h4>3. Romanticismo all-inclusive</h4><p>I resort si specializzano in esperienze romantiche senza pensieri. I butler possono organizzare di tutto, dalle proposte di matrimonio a sorpresa alle celebrazioni d''anniversario. La maggior parte offre pacchetti speciali per la luna di miele con extra romantici inclusi.</p><h4>4. Clima caldo tutto l''anno</h4><p>Con temperature medie di 28-30°C e temperature dell''acqua intorno ai 27°C tutto l''anno, le Maldive sono sempre pronte per una luna di miele. Sebbene esista una stagione delle piogge, gli acquazzoni sono solitamente brevi.</p><h4>5. Vita marina senza paragoni</h4><p>Gli atolli corallini delle Maldive creano condizioni perfette per una vita marina diversificata. Molti resort hanno eccellenti barriere coralline proprie dove è possibile fare snorkeling con tartarughe, razze e pesci tropicali direttamente dalla propria villa.</p><h2>I 5 migliori resort delle Maldive per la luna di miele</h2><figure><img src="legacy/resorts/four-seasons-huraa/images/four-seasons-maldives-at-kuda-huraa-sunset-water-bangalow1.webp" alt="Four Seasons Kuda Huraa overwater bungalow" loading="lazy" /></figure><h3>1. Four Seasons Resort Maldives at Kuda Huraa</h3><p>Questa leggendaria struttura stabilisce lo standard per le lune di miele alle Maldive, offrendo:</p><ul><li>Bungalow sull''acqua recentemente rinnovati con servizio di butler 24 ore su 24</li><li>Piscine a sfioro private nelle ville premium</li><li>Spa di fama mondiale con sale trattamento sull''acqua</li><li>Sette punti ristoro, inclusa una griglia di pesce sulla barriera</li><li>Escursioni gratuite per avvistare lo squalo balena in base alla stagione</li></ul><p>Pacchetto luna di miele: include champagne, massaggio di coppia, crociera privata al tramonto e cena romantica (soggiorno minimo di 5 notti)</p><p>Ideale per: coppie che desiderano servizio impeccabile e lusso</p><figure><img src="legacy/resorts/baros-island/images/baros-maldives-island-resort-beach-dinner.webp" alt="Baros Maldives beach dinner" loading="lazy" /></figure><h3>2. Baros Maldives</h3><p>Questo intimo resort boutique è perfetto per le coppie che cercano privacy:</p><ul><li>Solo 75 ville su una piccola isola privata</li><li>Ville immerse in una rigogliosa vegetazione per la massima privacy</li><li>Eccellente barriera coralline accessibile dalla spiaggia</li><li>Il celebre ristorante Lighthouse sulla laguna</li><li>Esperienze romantiche personalizzate</li></ul><p>Pacchetto luna di miele: include champagne, cestino di frutta, trattamento spa di 60 minuti e cena privata (soggiorno minimo di 4 notti)</p><p>Ideale per: coppie che apprezzano l''intimità e la bellezza naturale</p><h2>I pacchetti luna di miele alle Maldive spiegati</h2><figure><img src="legacy/images/romantic-sunrise-breakfast.webp" alt="Romantic breakfast in Maldives" loading="lazy" /></figure><p>Quasi tutti i resort maldiviani offrono pacchetti speciali per la luna di miele. Questi richiedono solitamente la prova del matrimonio avvenuto nei 6-12 mesi precedenti. Componenti principali:</p><h4>Dotazioni standard:</h4><ul><li>Champagne di benvenuto e cestino di frutta</li><li>Decorazione romantica del letto</li><li>Massaggio di coppia (solitamente 30-60 minuti)</li><li>Torta o dessert speciale per la luna di miele</li><li>Certificato commemorativo o regalo</li></ul><h4>Extra premium:</h4><ul><li>Crociera privata al tramonto</li><li>Cena in riva al mare sotto le stelle</li><li>Upgrade garantito della villa</li><li>Servizio fotografico con fotografo professionista</li><li>Escursioni personalizzate come il noleggio di yacht privati</li></ul><h2>Esperienze romantiche indimenticabili</h2><figure><img src="legacy/images/articles/ozen-maadhoo-underwater-restaurant.webp" alt="Underwater restaurant Maldives" loading="lazy" /></figure><h4>1. Cene sott''acqua</h4><p>Diversi resort dispongono di incredibili ristoranti sottomarini dove si cena circondati dalla vita marina. Il più famoso è Ithaa, al Conrad Maldives, il primo ristorante sottomarino al mondo interamente in vetro.</p><figure><img src="legacy/images/stargazing-on-the-maldives-beach.webp" alt="Stargazing in Maldives" loading="lazy" /></figure><h4>2. Osservazione privata delle stelle</h4><p>Con un inquinamento luminoso minimo, le Maldive offrono cieli notturni spettacolari. Alcuni resort forniscono telescopi e astronomi che vi guidano tra le costellazioni mentre vi rilassate sulla vostra terrazza privata.</p>', 'Luna di miele alle Maldive: la guida definitiva alla fuga romantica | Guida di Viaggio alle Maldive | MTG', 'Guida completa alla luna di miele alle Maldive: scoprite i migliori resort romantici, bungalow sull''acqua, pacchetti ed esperienze unica per la vostra vacanza di coppia perfetta nel paradiso.', 'published', 'claude')
on conflict (entity_id, locale) do update set
  slug = excluded.slug, title = excluded.title, short_description = excluded.short_description,
  body_html = excluded.body_html, meta_title = excluded.meta_title, meta_description = excluded.meta_description,
  translation_status = excluded.translation_status, translated_by = excluded.translated_by, updated_at = now();
